// Helper function to determine if a number is prime
function IsPrime(n: int) : bool
    requires n >= 0
    ensures Result == (n > 1 && forall k: int :: 2 <= k < n ==> n % k != 0)
{
    if n <= 1 {
        return false;
    }
    var i := 2;
    while i * i <= n
        invariant 2 <= i <= n
        invariant forall k: int :: 2 <= k < i ==> n % k != 0
    {
        if n % i == 0 {
            return false;
        }
        i := i + 1;
    }
    return true;
}
